script:
frappe.ui.form.on("Supplier", {
    setup(frm) {
        frm.set_query("region", function() {
            return {
                filters: {
                    country: frm.doc.country || ""
                }
            };
        });
    },

    country(frm) {
        frm.set_value("region", "");
    }
});
